  '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',
  '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',
];

for (const token of tokens) {
  try {
    const res = await fetch('https://api.github.com/user', {
      headers: { Authorization: `token ${token}` },
    });
    const data = await res.json();
    if (data.login) {
      console.log(`VALID: ${token.slice(0,12)}... login=${data.login}`);
    } else {
      console.log(`INVALID: ${token.slice(0,12)}... ${data.message}`);
    }
  } catch (e) {
    console.log(`ERROR: ${token.slice(0,12)}... ${e.message}`);
  }
}
